cedar_v1.text:
permit (principal, action == MCP::Action::"register", resource)
when { resource in MCP::Server::"crowdstrike" };

permit (principal, action == MCP::Action::"invokeTool", resource)
when { resource in MCP::Server::"crowdstrike" };

permit (principal, action == MCP::Action::"invokePrimordial", resource);

forbid (principal, action == MCP::Action::"invokeTool", resource)
when {
  resource in MCP::Server::"crowdstrike" &&
  (resource.name like "falcon_create_*" ||
   resource.name like "falcon_update_*" ||
   resource.name like "falcon_delete_*")
};
